import { forwardRef, type LabelHTMLAttributes } from "react";

export const Label = forwardRef<HTMLLabelElement, LabelHTMLAttributes<HTMLLabelElement>>(({ className = "", ...props }, ref) => (
  <label ref={ref} className={`co-text-sm co-font-medium co-leading-none has-[:disabled]:co-cursor-not-allowed has-[:disabled]:co-opacity-50 ${className}`.trim()} {...props} />
));
Label.displayName = "Label";
